// Direct input-device diagnostic for Phone Link/HFP investigation. No loopback flags are used.
#include <windows.h>
#include <mmdeviceapi.h>
#include <audioclient.h>
#include <functiondiscoverykeys_devpkey.h>
#include <cstdio>
#include <cwchar>
#include <string>
#include <vector>
#include <cmath>

static std::string utf8(const wchar_t* value) { if(!value)return ""; int n=WideCharToMultiByte(CP_UTF8,0,value,-1,nullptr,0,nullptr,nullptr); std::string out(n,'\0'); if(n){WideCharToMultiByte(CP_UTF8,0,value,-1,out.data(),n,nullptr,nullptr);out.pop_back();} return out; }
static std::string esc(const std::string& v) { std::string o; for(char c:v){if(c=='\\'||c=='\"'){o+='\\';o+=c;}else if(c=='\n')o+="\\n";else if(c=='\r')o+="\\r";else if((unsigned char)c<32)o+=' ';else o+=c;}return o; }
static const char* stateName(DWORD s){if(s==DEVICE_STATE_ACTIVE)return "ACTIVE";if(s==DEVICE_STATE_DISABLED)return "DISABLED";if(s==DEVICE_STATE_NOTPRESENT)return "NOTPRESENT";if(s==DEVICE_STATE_UNPLUGGED)return "UNPLUGGED";return "UNKNOWN";}
static std::string hexhr(HRESULT hr){char b[16];sprintf_s(b,"0x%08lX",(unsigned long)hr);return b;}
struct Metrics { unsigned long long samples=0; long double squares=0; int peak=0; void add(const BYTE* data,UINT32 frames,UINT16 ch){const short* p=(const short*)data; unsigned long long n=(unsigned long long)frames*ch;for(unsigned long long i=0;i<n;i++){int v=p[i],a=v<0?-v:v;if(a>peak)peak=a;squares+=(long double)v*v;}samples+=n;} double rms()const{return samples?sqrt((double)(squares/samples)):0;} };
static bool friendly(IMMDevice* d,std::string& name){IPropertyStore* store=nullptr;PROPVARIANT v;PropVariantInit(&v);bool ok=false;if(SUCCEEDED(d->OpenPropertyStore(STGM_READ,&store))){if(SUCCEEDED(store->GetValue(PKEY_Device_FriendlyName,&v))&&v.vt==VT_LPWSTR){name=utf8(v.pwszVal);ok=true;}store->Release();}PropVariantClear(&v);return ok;}
static void json(FILE* f,const std::string& name,const std::string& id,DWORD state,UINT32 rate,UINT16 channels,const Metrics& m,double seconds,const std::string& error){double rms=m.rms(); bool signal=error.empty()&&m.samples&&m.peak>=100&&rms>=20;fprintf(f,"{\"endpointName\":\"%s\",\"endpointId\":\"%s\",\"state\":\"%s\",\"sampleRate\":%u,\"channels\":%u,\"samples\":%llu,\"rms\":%.3f,\"peak\":%d,\"duration\":%.3f,\"signal\":%s,\"error\":%s}\n",esc(name).c_str(),esc(id).c_str(),stateName(state),rate,channels,m.samples,rms,m.peak,seconds,signal?"true":"false",error.empty()?"null":("\""+esc(error)+"\"").c_str());}
static int snapshot(const wchar_t* output){FILE* f=stdout;if(output&&_wfopen_s(&f,output,L"wb")!=0)return 1;IMMDeviceEnumerator* e=nullptr;HRESULT hr=CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_ALL,IID_PPV_ARGS(&e));if(FAILED(hr)){fprintf(f,"{\"error\":\"MMDeviceEnumerator\"}\n");return 1;}IMMDeviceCollection* c=nullptr;e->EnumAudioEndpoints(eCapture,DEVICE_STATEMASK_ALL,&c);UINT n=0;if(c)c->GetCount(&n);fprintf(f,"{\"kind\":\"capture-core-audio-snapshot\",\"endpoints\":[");bool first=true;for(UINT i=0;i<n;i++){IMMDevice*d=nullptr;c->Item(i,&d);if(!d)continue;LPWSTR id=nullptr;DWORD state=0;d->GetId(&id);d->GetState(&state);std::string name;friendly(d,name);std::string low=name;for(char&x:low)x=(char)tolower((unsigned char)x);bool callRelated=low.find("redmi")!=std::string::npos||low.find("hands-free")!=std::string::npos||low.find("hf audio")!=std::string::npos||low.find("phone")!=std::string::npos||low.find("bluetooth")!=std::string::npos;fprintf(f,"%s{\"endpointName\":\"%s\",\"endpointId\":\"%s\",\"state\":\"%s\",\"callRelatedName\":%s}",first?"":",",esc(name).c_str(),esc(utf8(id).c_str()).c_str(),stateName(state),callRelated?"true":"false");first=false;if(id)CoTaskMemFree(id);d->Release();}fprintf(f,"]}\n");if(c)c->Release();e->Release();if(f!=stdout)fclose(f);return 0;}
int wmain(int argc,wchar_t** argv){HRESULT co=CoInitializeEx(nullptr,COINIT_MULTITHREADED);if(FAILED(co))return 1;if(argc==3&&!wcscmp(argv[1],L"--snapshot")){int rc=snapshot(argv[2]);CoUninitialize();return rc;}const wchar_t* endpoint=nullptr;const wchar_t* wav=nullptr;double seconds=0;for(int i=1;i<argc;i++){if(!wcscmp(argv[i],L"--endpoint")&&i+1<argc)endpoint=argv[++i];else if(!wcscmp(argv[i],L"--seconds")&&i+1<argc)seconds=wcstod(argv[++i],nullptr);else if(!wcscmp(argv[i],L"--wav")&&i+1<argc)wav=argv[++i];else {CoUninitialize();return 2;}}Metrics m;std::string name,id=endpoint?utf8(endpoint):"",error;DWORD state=0;UINT32 rate=0;UINT16 channels=0;IMMDeviceEnumerator* en=nullptr;IMMDevice* dev=nullptr;IAudioClient* audio=nullptr;IAudioCaptureClient*capture=nullptr;HANDLE ev=nullptr;FILE* file=nullptr;HRESULT hr=S_OK;if(!endpoint||!wav||seconds<=0)error="usage: --endpoint <ID> --seconds <duration> --wav <output.wav>";else if(FAILED(hr=CoCreateInstance(__uuidof(MMDeviceEnumerator),nullptr,CLSCTX_ALL,IID_PPV_ARGS(&en))))error="MMDeviceEnumerator "+hexhr(hr);else if(FAILED(hr=en->GetDevice(endpoint,&dev)))error="GetDevice "+hexhr(hr);else{dev->GetState(&state);friendly(dev,name);if(FAILED(hr=dev->Activate(__uuidof(IAudioClient),CLSCTX_ALL,nullptr,(void**)&audio)))error="IAudioClient activation "+hexhr(hr);}WAVEFORMATEX fmt{};if(error.empty()){fmt.wFormatTag=WAVE_FORMAT_PCM;fmt.nChannels=2;fmt.nSamplesPerSec=48000;fmt.wBitsPerSample=16;fmt.nBlockAlign=4;fmt.nAvgBytesPerSec=192000;hr=audio->Initialize(AUDCLNT_SHAREMODE_SHARED,AUDCLNT_STREAMFLAGS_EVENTCALLBACK|AUDCLNT_STREAMFLAGS_AUTOCONVERTPCM,0,0,&fmt,nullptr);if(FAILED(hr))error="IAudioClient::Initialize "+hexhr(hr);else{rate=fmt.nSamplesPerSec;channels=fmt.nChannels;if(FAILED(hr=audio->GetService(IID_PPV_ARGS(&capture))))error="GetService "+hexhr(hr);}}if(error.empty()){ev=CreateEventW(nullptr,FALSE,FALSE,nullptr);if(!ev)error="CreateEvent";else if(FAILED(hr=audio->SetEventHandle(ev)))error="SetEventHandle "+hexhr(hr);}if(error.empty()&&_wfopen_s(&file,wav,L"wb")!=0)error="cannot open WAV";if(error.empty()){fwrite("RIFF",1,4,file);DWORD z=0,fmtSize=16;WORD pcm=1,align=fmt.nBlockAlign,bits=16;fwrite(&z,4,1,file);fwrite("WAVEfmt ",1,8,file);fwrite(&fmtSize,4,1,file);fwrite(&pcm,2,1,file);fwrite(&channels,2,1,file);fwrite(&rate,4,1,file);fwrite(&fmt.nAvgBytesPerSec,4,1,file);fwrite(&align,2,1,file);fwrite(&bits,2,1,file);fwrite("data",1,4,file);fwrite(&z,4,1,file);if(FAILED(hr=audio->Start()))error="Start "+hexhr(hr);}ULONGLONG until=GetTickCount64()+(ULONGLONG)(seconds*1000);while(error.empty()&&GetTickCount64()<until){if(WaitForSingleObject(ev,100)!=WAIT_OBJECT_0)continue;UINT32 packet=0;while(SUCCEEDED(capture->GetNextPacketSize(&packet))&&packet){BYTE*data=nullptr;UINT32 frames=0;DWORD flags=0;if(FAILED(hr=capture->GetBuffer(&data,&frames,&flags,nullptr,nullptr))){error="GetBuffer "+hexhr(hr);break;}size_t bytes=(size_t)frames*fmt.nBlockAlign;if(flags&AUDCLNT_BUFFERFLAGS_SILENT){std::vector<BYTE>zero(bytes);fwrite(zero.data(),1,bytes,file);m.samples+=(unsigned long long)frames*channels;}else{fwrite(data,1,bytes,file);m.add(data,frames,channels);}capture->ReleaseBuffer(frames);packet=0;}}if(audio)audio->Stop();if(file){DWORD bytes=(DWORD)(m.samples/channels*fmt.nBlockAlign);fseek(file,4,SEEK_SET);DWORD total=36+bytes;fwrite(&total,4,1,file);fseek(file,40,SEEK_SET);fwrite(&bytes,4,1,file);fclose(file);}json(stdout,name,id,state,rate,channels,m,seconds,error);if(ev)CloseHandle(ev);if(capture)capture->Release();if(audio)audio->Release();if(dev)dev->Release();if(en)en->Release();CoUninitialize();return error.empty()?0:1;}
